<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
use Illuminate\Database\Eloquent\Factories\HasFactory;
class HomeRemedy extends Model { use HasFactory,SoftDeletes; protected $fillable=['title_en','title_hi','slug','problem_name_en','problem_name_hi','short_description_en','short_description_hi','description_en','description_hi','ingredients_en','ingredients_hi','preparation_en','preparation_hi','steps_en','steps_hi','usage_instructions_en','usage_instructions_hi','dosage_or_quantity_en','dosage_or_quantity_hi','frequency_en','frequency_hi','recommended_duration_en','recommended_duration_hi','traditional_benefit_en','traditional_benefit_hi','how_it_may_help_en','how_it_may_help_hi','evidence_summary_en','evidence_summary_hi','evidence_level','suitable_for_en','suitable_for_hi','not_suitable_for_en','not_suitable_for_hi','child_warning_en','child_warning_hi','pregnancy_warning_en','pregnancy_warning_hi','elderly_warning_en','elderly_warning_hi','medical_condition_warning_en','medical_condition_warning_hi','medicine_interactions_en','medicine_interactions_hi','possible_side_effects_en','possible_side_effects_hi','red_flags_en','red_flags_hi','when_to_see_doctor_en','when_to_see_doctor_hi','medical_disclaimer_en','medical_disclaimer_hi','category_id','doctor_speciality_id','featured_image','thumbnail','meta_title_en','meta_title_hi','meta_description_en','meta_description_hi','search_keywords_en','search_keywords_hi','search_aliases','references','source_notes','is_featured','is_published','medical_review_status','reviewed_by','reviewed_at','sort_order']; protected $casts=['is_featured'=>'boolean','is_published'=>'boolean','reviewed_at'=>'datetime']; public function category(){return $this->belongsTo(HomeRemedyCategory::class,'category_id');} public function ingredients(){return $this->belongsToMany(HomeRemedyIngredient::class,'home_remedy_ingredient_map','home_remedy_id','ingredient_id')->withPivot('quantity','sort_order')->orderByPivot('sort_order');} public function speciality(){return $this->belongsTo(Department::class,'doctor_speciality_id');} public function scopePublished($q){return $q->where('is_published',true)->whereIn('medical_review_status',['medical_reviewed','published']);} public function getTranslation(string $field,string $locale):?string{return $this->{$field.'_'.$locale}??$this->{$field.'_en'};} public function getEvidenceLabelAttribute(){return ['traditional'=>'Traditional Use','limited'=>'Limited Evidence','supportive'=>'Some Supporting Evidence','moderate'=>'Moderate Evidence','strong'=>'Strong Evidence','not_recommended'=>'Not Recommended'][$this->evidence_level]??'Traditional Use';} public function searchableText():string{return implode(' ',array_filter([$this->title_en,$this->title_hi,$this->problem_name_en,$this->problem_name_hi,$this->short_description_en,$this->short_description_hi,$this->search_keywords_en,$this->search_keywords_hi,$this->search_aliases]));}}
